	@Test
	void coreDerivesAgeBand() throws Exception {
		ObjectNode o = ownerNode();
		o.put("birthDate", "1990-01-01");
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.ageBand").value("ADULT"));
