463	        currentOwner.setCity(ownerFieldsDto.getCity());
464	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
465	        currentOwner.setLastName(ownerFieldsDto.getLastName());
466	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
467	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
468	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
469	        this.clinicService.saveOwner(currentOwner);
470	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
471	    }
